// Generated by Suite Builder from a crawl of the site. What every test gets without asking: the steps, the cookie banner, ads blocked, evidence of a failure.
// EDIT RULES: edit only inside YOURS blocks; regenerating keeps them and rewrites the rest of this file.
// Runs before every spec: the suite's own commands, and what every test gets without asking.
import './core/Find';
import { Ads } from './core/Ads';
import { CookieBanner } from './core/CookieBanner';
import { StepLog } from './core/StepLog';

/** How many tests in a row may fail the same way before the run stops early (cypress.config.ts); 0: never. */
const STOP_AFTER = Number(Cypress.expose('stopAfter') ?? 5);
/** A pause between tests, in milliseconds, for a site the team does not own (--expose testDelay=1000); 0: none. */
const TEST_DELAY = Number(Cypress.expose('testDelay') ?? 0);
let firstTest = true;

/** The page's console errors and uncaught errors, this test. */
const consoleErrors: string[] = [];

// A site's own script errors are evidence, not a test failure (Cypress would fail the test on
// them by default): they are kept for the failure's console.txt.
Cypress.on('uncaught:exception', (error) => {
  consoleErrors.push(`uncaught: ${error.message}`);
  return false;
});
Cypress.on('window:before:load', (win) => {
  const original = win.console.error.bind(win.console);
  win.console.error = (...args: unknown[]) => {
    consoleErrors.push(`error: ${args.map(String).join(' ')}`);
    original(...args);
  };
});

beforeEach(function () {
  cy.task('runStopped', null, { log: false }).then((stopped) => {
    if (stopped) {
      cy.task('suiteLog', `   not run: the run stopped early, ${stopped}`, { log: false });
      this.skip();
    }
  });
  if (TEST_DELAY > 0 && !firstTest) cy.wait(TEST_DELAY, { log: false });
  firstTest = false;
  StepLog.start();
  CookieBanner.reset();
  consoleErrors.length = 0;
  cy.task('suiteLog', `-> ${Cypress.spec.name}: ${this.currentTest?.title ?? ''}`, { log: false });
  const blockAds = Cypress.expose('blockAds') as unknown;
  if (blockAds !== false && blockAds !== 'false') Ads.block();
});

/**
 * A folder or file name for a test: its title's first words and a hash of the whole title (which
 * keeps "/ -> /tinymce" and "/tinymce -> /" apart). Windows refuses paths over 260 characters, and a
 * title runs long ("/contact-us/ answered 404 in the crawl; linked from ...": 2026-10-01).
 */
function shortName(title: string): string {
  const words = title.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean).join('-');
  let hash = 0;
  for (const c of title) hash = (hash * 31 + c.charCodeAt(0)) | 0;
  return `${words.slice(0, 51).replace(/-$/, '')}-${(hash >>> 0).toString(16).padStart(8, '0')}`;
}

/**
 * A failed test leaves its evidence in cypress/failures/<spec>/<test, shortened>/: steps.txt (the
 * steps, the failed one marked, why, the URL and title), page.html, console.txt; and its screenshot,
 * by the same short name, in cypress/screenshots/.
 */
afterEach(function () {
  const test = this.currentTest;
  if (test?.state === 'passed') cy.task('testPassed', null, { log: false });
  if (!test || test.state !== 'failed') return;
  const error = (test as unknown as { err?: Error }).err ?? new Error('failed');
  cy.task('testFailed', { reason: StepLog.reason(error), stopAfter: STOP_AFTER, spec: Cypress.spec.name }, { log: false });
  const dir = `cypress/failures/${Cypress.spec.name}/${shortName(test.title)}`;
  const steps = StepLog.steps();
  cy.task('suiteLog', StepLog.failure(error), { log: false });
  cy.document({ log: false }).then((doc) => {
    // A page that never loaded has no body: Cypress's full-page screenshot fails on it, and a failure in
    // this hook skips the rest of the spec (Ghost's the-internet run, 2026-10-04). The runner's view instead.
    const loaded = Boolean(doc?.body && doc.documentElement);
    cy.screenshot(shortName(test.title), { log: false, overwrite: true, capture: loaded ? 'fullPage' : 'runner' });
    const lines = [test.fullTitle(), ''];
    steps.forEach((s, i) => lines.push(`${i + 1}. ${s}${i === steps.length - 1 ? '   <- FAILED HERE' : ''}`));
    lines.push('', `Because: ${error.message}`, `URL:     ${doc?.location?.href ?? '(none)'}`, `Title:   ${doc?.title ?? ''}`, '');
    cy.writeFile(`${dir}/steps.txt`, lines.join('\n'), { log: false });
    cy.writeFile(`${dir}/page.html`, loaded ? doc.documentElement.outerHTML : '<!-- the page never loaded -->\n', { log: false });
    cy.writeFile(`${dir}/console.txt`, consoleErrors.length ? `${consoleErrors.join('\n')}\n` : 'No console errors.\n', { log: false });
    cy.task('suiteLog', `   evidence: ${dir} (steps.txt, page.html, console.txt; screenshot in cypress/screenshots)`, { log: false });
  });
});

